#include <bits/stdc++.h>
using namespace std;

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    auto apply = [&](int x, int y){
        ops.push_back({x,y});
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
    };

    for(int target=0; target<n-1 && (int)ops.size()<4*n; target++){
        int pos=-1;
        for(int i=target;i<n;i++) if(p[i]==target+1){pos=i;break;}
        if(pos==target) continue;

        // Move element from pos to target
        // Step 1: move to position 0 using y = n - pos, x = 1 (if valid)
        // Element at pos: since pos >= n-y = pos, it goes to pos-(n-y) = 0
        // Need x=1, y=n-pos, x+y = n-pos+1 <= n-1 => pos >= 2
        // Also need middle to exist: n - y - x = pos - 1 >= 1 => pos >= 2

        if(pos >= 2){
            apply(1, n-pos); // element goes to position 0
            // Now element is at position 0, target is target
            if(target == 0) continue;
            // Move from 0 to target: x = target+1, y = 1 won't work directly
            // x=1, element at 0 goes to n-1. Then...
            // Use x = target, y = n - 1 - target if valid? No.
            // (x, y) with element at 0: goes to n-x+0 = n-target-1... hmm
            // Actually just: x=1, y=n-1-target. Element at 0 goes to n-1. 
            // Nope. Let me use: y = n-1-target, x = target+1... x+y=n, too big.
            apply(1, n-1-target); // element at 0 goes to end: pos n-1-(n-1-target)=target? No, goes to n-1.
            // Hmm, let me just recheck position after each op.
        } else {
            // pos is 0 or 1, handle specially
            if(pos==1 && target==0){ apply(1,1); continue; }
            if(pos==0){ apply(1, n-1-target); pos=n-1; /* now at end */ }
            if(pos==1){ apply(1,1); /* element goes somewhere */ }
        }
        // Recompute and retry if needed
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
